BEGIN;
-- Story 20.7, second round (A96, FR-133): the usage log writer becomes idempotent. When a COMMIT timed out on
-- the client side but had committed on the server, the buffer put the batch back and wrote it again (20
-- requests, 40 rows). The request id is generated by the server for every request (a client's X-Request-Id is
-- ignored, `request-id.middleware.ts`), so one id is one request: the writer now does
-- `INSERT ... ON CONFLICT ("requestId") DO NOTHING`, which needs a UNIQUE index on that column.
--
-- It REPLACES the plain index of the same column (queries by request id use it all the same), so the table
-- carries no extra index: the cost of a unique index over a uuid is the one of the plain one it replaces,
-- plus the uniqueness check at insert (docs/deployment.md 19.10 has the measurement).
--
-- Rows written twice before this migration are collapsed to the oldest one first; the table is mutable on
-- purpose (the purge and the anonymization delete from it) and holds at most 7 days. The unique index is built
-- without CONCURRENTLY (it cannot run inside the transaction): inserts into "Usage_Logs" WAIT while it is built
-- (reads do not); the buffer of the application retries a write that waits more than its 1 s lock_timeout and
-- loses nothing. An undeclared `lock_timeout` is deliberate (docs/deployment.md 12.2): deploy.sh bounds it.
DELETE FROM "Usage_Logs" a
 USING "Usage_Logs" b
 WHERE a."requestId" = b."requestId"
   AND a."id" > b."id";

DROP INDEX IF EXISTS "Usage_Logs_requestId_idx";
CREATE UNIQUE INDEX "Usage_Logs_requestId_key" ON "Usage_Logs" ("requestId");
COMMIT;
